def display_token(tok_info, context, verbose=False):
    # tok_info is dict with orig, is_class, tok
    # context is "outside" or "inside"
    # For classable (literal), display via escape_outside/inside based on orig char
    # For non-classable, display is tok directly (e.g. \d, \u{...})
    if tok_info["is_class"]:
        ch = tok_info["orig"]
        if context == "inside":
            return escape_inside(ch)
        else:
            return escape_outside(ch, verbose)
    else:
        return tok_info["tok"]

def tokens_equal(a, b):
    # a,b are tok_info dicts
    if a["is_class"] != b["is_class"]:
        return False
    if a["is_class"]:
        return a["orig"] == b["orig"]
    else:
        return a["tok"] == b["tok"]

def longest_common_prefix(strs):
    # strs: list of token lists (each token list is list of tok_info)
    # Returns length k (>=0) of longest prefix shared by all (where tokens_equal for each position)
    if not strs:
        return 0
    min_len = min(len(s) for s in strs)
    k = 0
    for i in range(min_len):
        first = strs[0][i]
        if all(tokens_equal(first, s[i]) for s in strs):
            k += 1
        else:
            break
    return k

def longest_common_suffix(strs):
    if not strs:
        return 0
    min_len = min(len(s) for s in strs)
    k = 0
    for i in range(1, min_len+1):
        first = strs[0][-i]
        if all(tokens_equal(first, s[-i]) for s in strs):
            k += 1
        else:
            break
    return k

def build_class(singles):
    # singles: list of token lists, each length1 and is_class True (single classable symbols)
    # Returns class string like [ab], [a-c], [\ -ab] etc.
    # singles are already deduped? Need to dedupe by orig char? Actually singles may have duplicates after mapping? For plain, 1 and 2 with -d both map to \d (non-classable, not here). For classable singles, duplicates are same orig char? E.g., a,a => deduped to one? Actually inputs deduped already, but after mapping, different originals could map to same literal? No, literals are 1:1 (each original maps to itself), so deduped inputs give deduped singles. Good. But need to sort by ord?
    # Collect unique orig chars, sorted by ord
    uniq = {}
    for tok_list in singles:
        ch = tok_list[0]["orig"]
        uniq[ord(ch)] = ch
    sorted_ords = sorted(uniq.keys())
    # Build parts with ranges for 3+ consecutive
    parts = []
    i = 0
    n = len(sorted_ords)
    while i < n:
        # Look ahead for consecutive run
        j = i
        while j+1 < n and sorted_ords[j+1] == sorted_ords[j] + 1:
            j += 1
        run_len = j - i + 1
        if run_len >= 3:
            # Range from sorted_ords[i] to sorted_ords[j]
            start_ch = uniq[sorted_ords[i]]
            end_ch = uniq[sorted_ords[j]]
            # Escape start/end for inside context? For range, start/end need escaping inside? For - etc., start may need escaping? Example [\--/] with start \- (escaped), end / (not). Good. So use escape_inside for start/end.
            # What about - as range operator? It's "-" (single hyphen, not escaped) between start and end.
            parts.append(escape_inside(start_ch) + "-" + escape_inside(end_ch))
            i = j + 1
        else:
            # Single or pair (1-2), no range, each escaped inside individually
            for k in range(i, j+1):
                parts.append(escape_inside(uniq[sorted_ords[k]]))
            i = j + 1
    inner = "".join(parts)
    return "[" + inner + "]"

